144:.sticky a,.sticky button{background:#fff;padding:14px 22px;border-radius:999px;font-weight:900;color:#241f1a;min-width:150px;text-align:center;border:none;cursor:pointer;font-size:16px;font-family:inherit}
160:button.speaker-card{border:none;text-align:left;cursor:pointer;font-family:inherit;width:100%;transition:.22s ease}
161:.speaker-hint{margin-top:12px;display:inline-flex;padding:8px 16px;border-radius:999px;background:var(--accent);color:#fff;font-weight:900;font-size:13px}
165:.speaker-photo{width:132px;aspect-ratio:1 / 1.2;border-radius:18px;background:linear-gradient(135deg,#f1e2cf,#e4d4bf);display:flex;align-items:center;justify-content:center;font-size:36px;font-weight:900;color:#8a6844;overflow:hidden;border:1px solid #e4d4bf}
168:.speaker-title{margin-top:2px;font-size:14px;font-weight:800;color:var(--accent)}
172:.speaker-link-btn:hover{background:var(--accent);border-color:var(--accent);color:#fff}
174:.btn-mini{display:inline-flex;padding:8px 16px;border-radius:999px;background:var(--accent);color:#fff;font-weight:900;font-size:13px}
194:.field input{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 14px;font-size:15px;font-family:inherit;outline:none;transition:.2s;background:#fffdf9;box-sizing:border-box}
195:.field input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(155,91,63,.18);background:#fff}
198:.field-check input{width:16px;height:16px;margin-top:3px;accent-color:var(--accent);flex-shrink:0}
200:.btn-ghost{flex:1;height:48px;border:1px solid var(--line);background:#fff;color:var(--text);font-weight:700;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;font-family:inherit}
202:.btn-submit{flex:1;height:48px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;font-weight:900;border:0;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;box-shadow:0 10px 24px -10px rgba(155,91,63,.55);font-family:inherit}
206:.success-icon{width:72px;height:72px;border-radius:50%;background:linear-gradient(135deg,#9ee9d3,#06C755);margin:0 auto 18px;display:grid;place-items:center;color:#fff;font-size:36px}
211:.btn-line-confirm{width:100%;height:50px;background:#06C755;color:#fff;font-weight:900;border:0;border-radius:12px;font-size:15px;cursor:pointer;transition:.2s;display:flex;align-items:center;justify-content:center;gap:8px;font-family:inherit}
